import { Injector, inject } from '@angular/core';
import { CanActivateFn, Router, Routes } from '@angular/router';

import { AppUtils } from './shared/app-utils';
import { CURRENT_PROFILE_FORM_VERSION } from './shared/core/common/constants';
import { hasOperatorRole } from './shared/core/common/user-role';
import { SessionService } from './shared/core/base/services/session.service';
import type { UserDto } from './shared/core/contracts/user.interface';

const loadEntryPage = () => import('./entry/components/entry-page/entry-page.component').then(m => m.EntryPageComponent);

const entryAreaGuard: CanActivateFn = async () => {
  const injector = inject(Injector);
  const sessionService = inject(SessionService);
  const router = inject(Router);
  const session = await sessionService.ensureSession();
  if (!session) {
    return true;
  }
  if (session.kind === 'operator-bootstrap') {
    return router.createUrlTree(['/operator']);
  }

  const { UsersService } = await import('./shared/core/base/services/users.service');
  const usersService = injector.get(UsersService);
  const user = usersService.peekCachedUserById(
    session.kind === 'demo' ? session.userId : session.profile.id
  );
  if (isAdminUser(user)) {
    return router.createUrlTree(['/admin']);
  }
  if (isOperatorUser(user)) {
    return router.createUrlTree(['/operator']);
  }
  return router.createUrlTree(['/game']);
};

const restrictedAreaGuard: CanActivateFn = async (_route, state) => {
  const injector = inject(Injector);
  const sessionService = inject(SessionService);
  const router = inject(Router);
  const session = await sessionService.ensureSession();
  if (session) {
    const { UsersService } = await import('./shared/core/base/services/users.service');
    const usersService = injector.get(UsersService);
    if (!usersService.localModeEnabled) {
      if (isBrowserOffline()) {
        if (session.kind === 'operator-bootstrap') {
          return entryRedirect(router, state.url);
        }
        const cachedUser = usersService.peekCachedUserById(
          session.kind === 'demo' ? session.userId : session.profile.id
        );
        if (isAdminUser(cachedUser)) {
          return router.createUrlTree(['/admin']);
        }
        if (isOperatorUser(cachedUser)) {
          return router.createUrlTree(['/operator']);
        }
        if (requiresProfileOnboarding(cachedUser)) {
          return entryRedirect(router, state.url);
        }
        return true;
      }
      const user = await usersService
        .loadUserById(session.kind === 'demo' ? session.userId : undefined, 8000)
        .catch(() => null);
      if (!user) {
        return entryRedirect(router, state.url);
      }
      if (isAdminUser(user)) {
        return router.createUrlTree(['/admin']);
      }
      if (isOperatorUser(user)) {
        return router.createUrlTree(['/operator']);
      }
      if (requiresProfileOnboarding(user)) {
        return router.createUrlTree(['/entry'], {
          queryParams: {
            redirect: state.url && state.url !== '/' ? state.url : '/game',
            onboarding: '1'
          }
        });
      }
    }
    return true;
  }
  return router.createUrlTree(['/entry'], {
    queryParams: state.url && state.url !== '/' ? { redirect: state.url } : undefined
  });
};

const operatorAreaGuard: CanActivateFn = async (_route, state) => {
  const injector = inject(Injector);
  const sessionService = inject(SessionService);
  const router = inject(Router);
  const session = await sessionService.ensureSession();
  if (!session) {
    return entryRedirect(router, state.url);
  }

  const { UsersService } = await import('./shared/core/base/services/users.service');
  const usersService = injector.get(UsersService);
  const user = await usersService
    .loadUserById(session.kind === 'demo' ? session.userId : undefined)
    .catch(() => null);
  if (isOperatorUser(user)) {
    return true;
  }
  if (isAdminUser(user)) {
    return router.createUrlTree(['/admin']);
  }
  if (user) {
    return router.createUrlTree(['/game']);
  }
  return entryRedirect(router, state.url);
};

const adminAreaGuard: CanActivateFn = async (_route, state) => {
  const injector = inject(Injector);
  const sessionService = inject(SessionService);
  const router = inject(Router);
  const session = await sessionService.ensureSession();
  if (!session) {
    return entryRedirect(router, state.url);
  }

  const { UsersService } = await import('./shared/core/base/services/users.service');
  const usersService = injector.get(UsersService);
  if (session.kind === 'demo' && usersService.localModeEnabled) {
    const { AdminWorkspaceStore } = await import('./shared/ui/context/stores/admin-workspace.store');
    const adminWorkspace = injector.get(AdminWorkspaceStore);
    const userId = session.userId.trim();
    const storedAdminId = adminWorkspace.readStoredAdminId();
    if (userId && (userId === storedAdminId || userId.startsWith('admin-demo-'))) {
      return true;
    }
    return entryRedirect(router, state.url);
  }

  const user = await usersService
    .loadUserById(session.kind === 'demo' ? session.userId : undefined)
    .catch(() => null);
  if (isAdminUser(user)) {
    return true;
  }
  return entryRedirect(router, state.url);
};

function entryRedirect(router: Router, redirectUrl: string) {
  return router.createUrlTree(['/entry'], {
    queryParams: redirectUrl && redirectUrl !== '/' ? { redirect: redirectUrl } : undefined
  });
}

function requiresProfileOnboarding(user: UserDto | null | undefined): boolean {
  if (
    !user
    || isAdminUser(user)
    || isOperatorUser(user)
    || user.profileStatus === 'blocked'
    || user.profileStatus === 'deleted'
  ) {
    return false;
  }
  return user.profileStatus === 'onboarding'
    || AppUtils.positiveInteger(user.profileFormVersion) < CURRENT_PROFILE_FORM_VERSION;
}

function isAdminUser(user: UserDto | null | undefined): boolean {
  return user?.admin === true || `${user?.hostTier ?? ''}`.trim().toLowerCase() === 'admin';
}

function isOperatorUser(user: UserDto | null | undefined): boolean {
  return hasOperatorRole(user);
}

function isBrowserOffline(): boolean {
  return typeof navigator !== 'undefined' && navigator.onLine === false;
}

export const routes: Routes = [
  {
    path: '',
    pathMatch: 'full',
    canActivate: [entryAreaGuard],
    loadComponent: loadEntryPage
  },
  {
    path: 'entry',
    loadComponent: loadEntryPage
  },
  {
    path: 'privacy-policy',
    loadComponent: () => import('./shared/ui/components/document-viewer/document-viewer.component').then(m => m.DocumentViewerComponent),
    data: { documentKind: 'privacy' }
  },
  {
    path: 'terms',
    loadComponent: () => import('./shared/ui/components/document-viewer/document-viewer.component').then(m => m.DocumentViewerComponent),
    data: { documentKind: 'terms' }
  },
  {
    path: 'admin/help/:token',
    loadComponent: () => import('./admin/components/admin-help-session-page/admin-help-session-page.component').then(m => m.AdminHelpSessionPageComponent)
  },
  {
    path: 'admin',
    canActivate: [adminAreaGuard],
    loadChildren: () => import('./admin/admin.module').then(m => m.AdminModule)
  },
  {
    path: 'operator',
    canActivate: [operatorAreaGuard],
    loadComponent: () => import('./operator/components/operator-page/operator-page.component')
      .then(m => m.OperatorPageComponent)
  },
  {
    path: '',
    canActivate: [restrictedAreaGuard],
    children: [
      { path: 'home', redirectTo: 'game', pathMatch: 'full' },
      {
        path: 'game',
        loadComponent: () => import('./home/components/home/home.component').then(m => m.HomeComponent),
        data: { section: 'game' }
      }
    ]
  },
  { path: '**', redirectTo: '' }
];
